        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastRecord = history[history.length - 1];
            var results = lastRecord.results || {};
            var finalEmissions = results.emissions || 0;
            var trajectoryScore = results.trajectoryScore || 0;
            var abatementPct = results.abatementPct || 0;
            var creditQuality = results.creditQuality || 0;

            var totalCost = 0;
            for (var i = 0; i < history.length; i++) {
                totalCost += (history[i].results || {}).totalRoundCost || 0;
            }

            var cbamBonus = 0;
            if (history.length >= 5) {
                var lastCbam = (history[history.length - 1].results || {}).cbamCost || 0;
                var firstCbam = (history[1] && history[1].results) ? history[1].results.cbamCost || 0 : 0;
                if (firstCbam > 0 && lastCbam < firstCbam * 0.6) cbamBonus = 5;
            }

            var compliancePenalty = 0;
            for (var j = 0; j < history.length; j++) {
                if ((history[j].results || {}).compliance === 'amber') compliancePenalty += 1;
                if ((history[j].results || {}).compliance === 'red') compliancePenalty += 3;
            }

            var finalScore = Math.min(100, Math.round(
                trajectoryScore * 0.35 +
                abatementPct * 0.25 +
                Math.max(0, 100 - totalCost * 0.8) * 0.20 +
                creditQuality * 0.15 +
                Math.max(0, (100 - compliancePenalty * 10)) * 0.05 +
                cbamBonus
            ));

            var performance = 'Stranded Position';
            if (finalScore >= 90) performance = 'Climate Leader';
            else if (finalScore >= 75) performance = 'Credible Transition';
            else if (finalScore >= 60) performance = 'Compliance Player';

            var insights = [];
            if (trajectoryScore >= 80) insights.push('Strong trajectory toward 2030 SBTi target.');
            else insights.push('SBTi 2030 target at risk. More real abatement is needed.');
            if (abatementPct >= 60) insights.push('Good progress on the abatement cost curve.');
            else insights.push('Abatement investment was insufficient. Offset-heavy strategies fail the SBTi standard.');
            if (creditQuality >= 75) insights.push('Voluntary credit portfolio maintained high quality.');
            else insights.push('Credit quality suffered. Diversification and due diligence are essential.');
            if (cbamBonus > 0) insights.push('CBAM optimization bonus earned through emissions intensity reduction.');

            return {
                finalScore: finalScore,
                finalEmissions: finalEmissions,
                sbtiTarget: 812580,
                totalCarbonCost: Math.round(totalCost * 10) / 10,
                abatementProgress: abatementPct + '%',
                creditQualityAvg: creditQuality,
                performance: performance,
                insights: insights
            };
        }

